// Trocear respuesta del agente en HASTA 4 mensajes (estilo Tomi Babilonia)
// Prioriza cortes naturales por párrafos (\n\n), luego por frases (. ! ?)

const respuesta = (
  $input.first().json.output?.respuesta
  || $input.first().json.respuesta
  || "Sin respuesta"
).trim();

const MAX_MENSAJES = 4;
const MAX_CHARS = 3500; // límite seguro por mensaje (Telegram permite 4096)

// Si es cortita y sin párrafos, mandar un solo mensaje
if (respuesta.length <= MAX_CHARS && !respuesta.includes("\n\n")) {
  return [{ json: { mensaje: respuesta } }];
}

// 1) Partir por párrafos (doble salto de línea)
let bloques = respuesta.split(/\n\s*\n/).map(b => b.trim()).filter(Boolean);

// 2) Si hay más de 4 bloques, agrupar para tener máximo 4
if (bloques.length > MAX_MENSAJES) {
  const objetivoPorBloque = Math.ceil(bloques.length / MAX_MENSAJES);
  const agrupados = [];
  for (let i = 0; i < bloques.length; i += objetivoPorBloque) {
    agrupados.push(bloques.slice(i, i + objetivoPorBloque).join("\n\n"));
  }
  bloques = agrupados;
}

// 3) Si algún bloque pasa MAX_CHARS, cortarlo respetando frases
const resultado = [];
for (const bloque of bloques) {
  if (bloque.length <= MAX_CHARS) {
    resultado.push(bloque);
    continue;
  }
  // bloque largo → cortar por frases
  const frases = bloque.match(/[^.!?]+[.!?]+(\s|$)|[^.!?]+$/g) || [bloque];
  let buffer = "";
  for (const frase of frases) {
    if ((buffer + frase).length > MAX_CHARS && buffer) {
      resultado.push(buffer.trim());
      buffer = frase;
    } else {
      buffer += frase;
    }
  }
  if (buffer.trim()) resultado.push(buffer.trim());
}

// 4) Si quedaron más de 4 mensajes igual, fusionar los últimos
while (resultado.length > MAX_MENSAJES) {
  const ultimo = resultado.pop();
  resultado[resultado.length - 1] += "\n\n" + ultimo;
}

// 5) Devolver cada mensaje como un item separado para el Loop
return resultado.map(mensaje => ({ json: { mensaje } }));

